/*global __dirname:readonly*/
"use strict";

var binary = require("@mapbox/node-pre-gyp"),
  path = require("path"),
  binding_path = binary.find(
    path.resolve(path.join(__dirname, "../package.json"))
  ),
  nativeMetrics = require(binding_path),
  gcAggregatedStats = require("./GcAggregatedStats"),
  gcMetricsAggs = new gcAggregatedStats();

nativeMetrics.afterGC(function (stats) {
  gcMetricsAggs.aggregateStats(stats);
});

var native = {
  getStats: function () {
    let finalJsonData = {};
    finalJsonData.gc = gcMetricsAggs.getAsJsonArray();
    gcMetricsAggs.reset();
    finalJsonData.event_loop_metrics = nativeMetrics.read();
    return finalJsonData;
  }
};

module.exports = native;
